// thread (the gh-744 never-resolve-humans doctrine).
function normalizedMachineLogins(opts) {
    var logins = [];
    ((opts && opts.machineLogins) || []).forEach(function (l) {
        if (l) logins.push(String(l).toLowerCase());
    });
